mapper.select:
SELECT o.status AS status, COUNT(*) AS order_count, COALESCE(SUM(o.total_amount), 0) AS total_amount, COALESCE(SUM(o.pay_amount), 0) AS pay_amount FROM shop_order o WHERE o.deleted = 0
AND o.create_time >= #{startTime}
AND o.create_time < #{endTime}
GROUP BY o.status ORDER BY o.status ASC

SELECT o.pay_type AS pay_type, COUNT(*) AS order_count, COALESCE(SUM(o.pay_amount), 0) AS pay_amount FROM shop_order o WHERE o.deleted = 0
AND o.create_time >= #{startTime}
AND o.create_time < #{endTime}
GROUP BY o.pay_type ORDER BY o.pay_type ASC
